% exercise4.m
x = [1 1 1 1];
n = 0:length(x)-1;

% DTFT at 1000 frequencies between -pi and pi
w = linspace(-pi, pi, 1000);
X = x * exp(-1j * (n.' * w));

% DFTs (fft(x,N) zero-pads x to length N)
X4  = fft(x, 4);
X64 = fft(x, 64);

% Frequency axes for the DFTs, shifted to run from -pi to pi
w4  = 2*pi*(-2:1)/4;
w64 = 2*pi*(-32:31)/64;

figure %[output:7ed5b03b]
subplot(3,1,1) %[output:7ed5b03b]
plot(w, abs(X)); grid on %[output:7ed5b03b]
ylabel('Magnitude'); title('DTFT (1000 points)') %[output:7ed5b03b]

subplot(3,1,2) %[output:7ed5b03b]
stem(w4, abs(fftshift(X4)), 'filled'); grid on %[output:7ed5b03b]
ylabel('Magnitude'); title('DFT, fft(x,4)') %[output:7ed5b03b]

subplot(3,1,3) %[output:7ed5b03b]
plot(w, abs(X), 'Color', [0.7 0.7 0.7]); hold on %[output:7ed5b03b]
stem(w64, abs(fftshift(X64)), 'filled'); grid on %[output:7ed5b03b]
xlabel('Angular frequency (rad/sample)'); ylabel('Magnitude') %[output:7ed5b03b]
title('DFT, fft(x,64), over the DTFT') %[output:7ed5b03b]

for a = 1:3
    subplot(3,1,a); xlim([-pi pi]) %[output:7ed5b03b]
end

exportgraphics(gcf, 'dtft-dft-comparison.png', 'Resolution', 300) %[output:7ed5b03b]

disp(abs(X4))   % print the 4-point DFT magnitudes %[output:40f96d63]

